import XCTest
@testable import PhotoCraftCore

final class LayerCollectionTransformTests:XCTestCase{
  func fixture(_ depth:PixelDepth = .u8)throws->CraftDocument{
    var d=try CraftDocument(width:20,height:16,depth:depth),a=Layer(name:"A",content:.raster(try Surface(width:3,height:2,depth:depth,fill:Pixel(1,0,0)))),b=Layer(name:"B",content:.raster(try Surface(width:4,height:3,depth:depth,fill:Pixel(0,0,1))))
    a.x=2;a.y=3;b.x=9;b.y=6;d.layers=[a,b];d.activeLayerID=b.id;return d
  }
  func testCommonThreeDepthTransformsPreserveOrderIdentityAndIndependentPivot()throws{
    for depth in PixelDepth.allCases{let source=try fixture(depth),ids=source.layers.map(\.id);for matrix in [Transform2D.translation(5,3),.translation(15,0) * .scale(-1,1),.translation(12,8) * .rotation(90) * .translation(-12,-8)]{var d=source;try Command.transformLayers(.init(layerIDs:ids,matrix:matrix,interpolation:.nearest)).apply(to:&d);XCTAssertEqual(d.layers.map(\.id),ids);XCTAssertEqual(d.activeLayerID,source.activeLayerID);for i in 0..<2{let before=source.layers[i].coordinateTransform.point(0.5,0.5),expected=matrix.point(before.x,before.y);if case .raster(let p)=d.layers[i].content,case .raster(let original)=source.layers[i].content{XCTAssertEqual(p.depth,depth);let local=try d.layers[i].coordinateTransform.inverted().point(expected.x,expected.y);XCTAssertEqual(p.pixel(x:Int(floor(local.x)),y:Int(floor(local.y))),original.pixel(x:0,y:0),"Original pixel must arrive at the common transformed document coordinate")};XCTAssertEqual(d.layers[i].parentID,source.layers[i].parentID)};try d.validate()}}
  }
  func testParentChildSelectionNormalizesOnceAndRetainsGroupMaskCoordinates()throws{
    var source=try fixture();let child=source.layers[0].id;try Command.groupLayers(source.layers.map(\.id),"Group").apply(to:&source);let group=try XCTUnwrap(source.activeLayerID),i=try XCTUnwrap(source.layers.firstIndex{$0.id==group});source.layers[i].mask=try Surface(width:20,height:16,fill:.white);var properties=MaskProperties();properties.linked=false;source.layers[i].maskProperties=properties
    var d=source;try Command.transformLayers(.init(layerIDs:[group,child],matrix:.translation(5,3),interpolation:.nearest)).apply(to:&d);XCTAssertEqual(try LayerCollectionTransform.roots(source,layerIDs:[group,child]).map(\.id),[group]);for layer in source.layers{let after=try XCTUnwrap(d.layers.first{$0.id==layer.id});XCTAssertEqual(after.parentID,layer.parentID);if layer.id==child{XCTAssertEqual(after.x,layer.x+5);XCTAssertEqual(after.y,layer.y+3)}};XCTAssertEqual(d.layers[i].maskCoordinateTransform,source.layers[i].maskCoordinateTransform);XCTAssertEqual(d.layers[i].mask,source.layers[i].mask)
  }
  func testEditableTextShapeMasksAndStyleParametersSurviveAffineSkew()throws{
    var d=try fixture(.u16);let text=Layer(name:"Type",content:.text(TextContent(text:"Owned",fontName:"HelveticaNeue",size:14,color:.black))),shape=Layer(name:"Shape",content:.shape(ShapeContent(kind:.rectangle,width:3,height:4,color:.white)));d.layers += [text,shape];d.layers[0].mask=try Surface(width:3,height:2,depth:.u16,fill:.white);d.layers[0].maskProperties=MaskProperties();d.layers[0].style=LayerStyle();let source=d,matrix=Transform2D(a:1,b:0.1,c:0.3,d:1,tx:2,ty:-1);try Command.transformLayers(.init(layerIDs:d.layers.map(\.id),matrix:matrix)).apply(to:&d);guard case .text(let afterText)=d.layers[2].content,case .shape(let afterShape)=d.layers[3].content else{return XCTFail("Flattened editable content")};XCTAssertEqual(afterText.text,"Owned");XCTAssertEqual(afterText.size,14);XCTAssertEqual(afterShape,try {if case .shape(let value)=source.layers[3].content{return value};throw CraftError.invalid("Missing shape")}());XCTAssertEqual(d.layers[0].style,source.layers[0].style);XCTAssertEqual(d.layers[0].maskCoordinateTransform,matrix*source.layers[0].maskCoordinateTransform)
  }
  func testLockedDescendantBackgroundUnknownDuplicateAndSelectionFailAtomically()throws{
    let source=try fixture();for mode in 0..<5{var d=source;var ids=d.layers.map(\.id);switch mode{case 0:d.layers[0].protection = .position;case 1:d.layers[0].content = .raster(try Surface(width:20,height:16,fill:.white));d.layers[0].x=0;d.layers[0].y=0;d.layers[0].background=true;case 2:ids=[UUID()];case 3:ids=[ids[0],ids[0]];default:d.selection = .init(x:0,y:0,width:2,height:2)};let before=d;XCTAssertThrowsError(try Command.transformLayers(.init(layerIDs:ids,matrix:.translation(1,0))).apply(to:&d));XCTAssertEqual(d,before)}
    var group=source;try Command.groupLayers(group.layers.map(\.id),"Group").apply(to:&group);group.layers[0].protection = .position;let before=group;XCTAssertThrowsError(try Command.transformLayers(.init(layerIDs:[try XCTUnwrap(group.activeLayerID)],matrix:.translation(1,0))).apply(to:&group));XCTAssertEqual(group,before)
  }
  func testOneHistoryAndPortableActionsPreserveSelectionUndoRedoAndStaleGuard()throws{
    let source=try fixture();var session=EditorSession(document:source);try session.startActionRecording(name:"Layers");let command=Command.transformLayers(.init(layerIDs:source.layers.map(\.id),matrix:.translation(5,3),interpolation:.nearest));try session.execute(command);let result=session.document;XCTAssertEqual(session.undoStack.count,1);XCTAssertEqual(session.undoStack.last?.label,"Free Transform");var replay=source;try XCTUnwrap(session.actionRecording?.snapshot).apply(to:&replay);XCTAssertEqual(replay,result);try session.undo();XCTAssertEqual(session.document,source);try session.redo();XCTAssertEqual(session.document,result);let edit=try PreparedEdit(command:command,document:source);XCTAssertThrowsError(try session.executePrepared(edit));XCTAssertEqual(session.document,result)
  }
  func testIdentityInvalidAndCancelledRequestsPublishNothing()async throws{
    let source=try fixture(),ids=source.layers.map(\.id);var session=EditorSession(document:source);try session.execute(.transformLayers(.init(layerIDs:ids,matrix:.identity)));XCTAssertTrue(session.undoStack.isEmpty);var d=source;XCTAssertThrowsError(try Command.transformLayers(.init(layerIDs:ids,matrix:.scale(0,1))).apply(to:&d));XCTAssertEqual(d,source);let task=Task{while !Task.isCancelled{await Task.yield()};var d=source;try Command.transformLayers(.init(layerIDs:ids,matrix:.translation(1,0))).apply(to:&d)};task.cancel();do{try await task.value;XCTFail("Canceled collection published")}catch{XCTAssertTrue(error is CancellationError)}
  }
  func testSparseMaximumLayersMoveWithoutNewAdmissionLimit()throws{
    var d=try CraftDocument(width:300000,height:300000),s=try Surface(width:300000,height:300000);s.setPixel(x:65,y:65,.white);let a=Layer(name:"A",content:.raster(s)),b=Layer(name:"B",content:.raster(s));d.layers=[a,b];d.activeLayerID=b.id;try Command.transformLayers(.init(layerIDs:[a.id,b.id],matrix:.translation(32,16),interpolation:.nearest)).apply(to:&d);for layer in d.layers{XCTAssertEqual(layer.x,32);XCTAssertEqual(layer.y,16);guard case .raster(let surface)=layer.content else{return XCTFail()};XCTAssertLessThan(surface.allocatedBytes,2_097_152);XCTAssertEqual(surface.pixel(x:65,y:65),.white)}
  }
}
